{
  "lecture": [
    {
      "etiquette": "F31",
      "R1": {
        "valeur": 1,
        "passage": "À coût d'appels égal (l'ajout ne représente que quelques dizaines de jetons d'entrée), la part des propositions brutes explorant des couples de traits absents de l'archive augmente d'au moins 30 %"
      },
      "R2": {
        "valeur": 1,
        "passage": "Mesure par l'oracle : nombre de composantes plantées couvertes (D2) et taux de fausses découvertes à coût égal"
      },
      "R3": {
        "valeur": 1,
        "passage": "Insérer cette table de comptage purement descriptive dans la vue publique à côté de la liste complète des lois de l'archive, sans aucune consigne prescriptive, ni quota, ni score."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "pour chaque paire (t_i, t_j), le nombre de lois où t_i apparaît dans une condition (`si_sinon` ou `par_sous_population`) et t_j dans la branche prédite."
      },
      "R6": {
        "valeur": 1,
        "passage": "vérifier par l'oracle sur les cartes brutes si de nouvelles composantes plantées sont touchées (coût : quelques dollars d'appels)."
      },
      "R7": {
        "valeur": 0,
        "motif": "La table rend les fréquences syntaxiques visibles, mais aucune raison donnée n'implique leur évitement plutôt que leur imitation, ni une meilleure couverture des composantes conditionnelles."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F32",
      "R1": {
        "valeur": 1,
        "passage": "À dollars égaux, le nombre de composantes plantées distinctes touchées par les propositions brutes augmente d'au moins 30 % en relatif par monde et par génération."
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle lu une fois : composantes couvertes aux trois étages, lois fausses et copies promues."
      },
      "R3": {
        "valeur": 1,
        "passage": "La seule information échangée est le texte des pairs, jamais un verdict. Le regroupement des doublons, déjà mécanique, donne au rappel un contenu factuel plutôt qu'une prime."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:composition"
      },
      "R5": {
        "valeur": 1,
        "passage": "les cartes extraites des réponses brutes scellées des rangs 1 à k−1, sans tri et sans mention du gardien"
      },
      "R6": {
        "valeur": 1,
        "passage": "20 mondes, 3 bras (témoin, chaîne, placebo), 2 générations, 4 proposeurs, environ 480 appels, soit quelques centaines de dollars."
      },
      "R7": {
        "valeur": 1,
        "passage": "Un proposeur qui voit qu'un constat est déjà proposé, avec le rappel factuel qu'une carte reprenant une carte déjà proposée sera regroupée avec elle, porte ses cartes ailleurs."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F33",
      "R1": {
        "valeur": 1,
        "passage": "le nombre de copies promues diminue d'au moins 5 % par rapport à la course de référence"
      },
      "R2": {
        "valeur": 1,
        "passage": "nombre de copies promues, lu par l'oracle après la course ; témoin : une modification tirée au hasard, au même coût"
      },
      "R3": {
        "valeur": 1,
        "passage": "Le reste de l'organisme ne change pas : mêmes proposeurs, même juge, mêmes plafonds, même monde."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:cout"
      },
      "R5": {
        "valeur": 0,
        "motif": "La demande ne précise pas quelle quantité le plafond borne ni comment le tripler tout en conservant le budget annoncé."
      },
      "R6": {
        "valeur": 1,
        "passage": "quelques dollars d'appels par graine"
      },
      "R7": {
        "valeur": 0,
        "motif": "Dire que les groupes de doublons se forment autrement ne donne aucune raison impliquant une diminution des copies promues."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F34",
      "R1": {
        "valeur": 1,
        "passage": "le coût en dollars par génération diminue d'au moins 20 % par rapport à la course de référence"
      },
      "R2": {
        "valeur": 1,
        "passage": "coût en dollars par génération, relevé par les relais ; témoin : une modification tirée au hasard, au même coût"
      },
      "R3": {
        "valeur": 1,
        "passage": "Le reste de l'organisme ne change pas : mêmes proposeurs, même juge, mêmes plafonds, même monde."
      },
      "R4": {
        "valeur": 0,
        "motif": "La fiche ne nomme aucune garantie conservée ni le nul contre lequel elle resterait démontrable."
      },
      "R5": {
        "valeur": 1,
        "passage": "Tripler le nombre m fixé d'avance pour la règle de Benjamini et Hochberg sur les valeurs e."
      },
      "R6": {
        "valeur": 1,
        "passage": "quelques dollars d'appels par graine"
      },
      "R7": {
        "valeur": 0,
        "motif": "La réaction des proposeurs à la forme de leur vue n'explique pas l'effet d'un paramètre interne du juge sur les dollars dépensés."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F35",
      "R1": {
        "valeur": 1,
        "passage": "à coût égal en tirages frais, au moins deux composantes plantées de plus couvertes par monde, et pas plus d'une loi fausse promue sur quarante mondes"
      },
      "R2": {
        "valeur": 1,
        "passage": "composantes plantées couvertes et lois fausses promues, lues par l'oracle après la course ; témoin à coût égal : le juge actuel avec le même nombre de tirages frais"
      },
      "R3": {
        "valeur": 0,
        "motif": "La validation individuelle au seuil 1/α remplace la règle de promotion sans conserver de contrôle des comparaisons multiples entre cartes."
      },
      "R4": {
        "valeur": 1,
        "passage": "ce qui contrôle l'erreur de première espèce au niveau α même quand on décide en cours de route d'ajouter ou d'arrêter des expériences."
      },
      "R5": {
        "valeur": 0,
        "motif": "La demande ne spécifie ni les expériences admissibles, ni le calcul des valeurs p, ni leur conversion en valeurs e conditionnellement valides pour le produit."
      },
      "R6": {
        "valeur": 1,
        "passage": "quelques dollars d'appels par génération pour l'agent qui conçoit les expériences"
      },
      "R7": {
        "valeur": 0,
        "motif": "La garantie sous arrêt optionnel ne fournit aucune raison impliquant une couverture supérieure à nombre de tirages égal."
      },
      "N": {
        "valeur": "C2",
        "passage_fiche": "chaque expérience rend une valeur p, convertie en valeur e ; les valeurs e se combinent au fil des expériences, et la carte n'est validée que si la valeur e combinée dépasse 1/α",
        "passage_catalogue": "chaque valeur p est convertie en **valeur e** ; les valeurs e se combinent ; l'hypothèse est validée quand la valeur e combinée dépasse 1/α"
      }
    }
  ]
}
